import logging
import os
import pathlib
import subprocess
from starlette.middleware.base import BaseHTTPMiddleware

class PassthroughAuth(BaseHTTPMiddleware):
    async def dispatch(self, request, call_next):
        return await call_next(request)

def check_encrypted_volume(db_dir) -> None:
    try:
        if os.name == 'nt':
            result = subprocess.run(['manage-bde', '-status', str(pathlib.Path(db_dir).anchor)], capture_output=True, text=True, timeout=10)
            if 'Percentage Encrypted: 100' not in result.stdout:
                logging.warning('DB dir %s may not be on an encrypted volume', db_dir)
        else:
            result = subprocess.run(['cryptsetup', 'status', str(pathlib.Path(db_dir).anchor)], capture_output=True, text=True, timeout=10)
            if 'is active' not in result.stdout:
                logging.warning('DB dir %s may not be on an encrypted volume', db_dir)
    except Exception as e:
        logging.warning(f'Error checking encrypted volume: {e}')
